//
//  StashTests.swift
//  MizarKitTests
//
//  The offline stash, against the cross-language fixture.
//
//  `protocol/fixtures/stash/vectors.json` is generated by
//  `tools/gen-stash-fixtures.mjs` and read by the desktop's tests as well, so a
//  derivation or framing drift on either side fails here rather than in the
//  field as a bundle that silently never opens. The rest of the suite covers the
//  behaviour a bundle's contents drive: decoding, the two merge branches, and
//  the two ways a pull degrades (no stash, unreadable envelope).
//

import CryptoKit
import Foundation
import Testing
@testable import MizarKit

// MARK: - The fixture

/// `protocol/fixtures/stash/vectors.json`, as this suite reads it.
private struct StashVectors: Decodable {
    let v: Int
    let derivation: Derivation
    let envelopes: [Envelope]

    struct Derivation: Decodable {
        let token: String
        let room: String
        let tokenHash: String
        let key: String
        let cred: String
    }

    struct Envelope: Decodable {
        let name: String
        let bundleId: String
        let createdAt: Int64
        /// Hex, lowercase.
        let nonce: String
        let aad: String
        let plaintext: String
        /// Base64, as the generator writes it.
        let envelope: String
    }
}

/// Where the fixture lives, from this file's own path.
private var stashVectorsURL: URL {
    URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()  // MizarKitTests
        .deletingLastPathComponent()  // Tests
        .deletingLastPathComponent()  // MizarKit
        .deletingLastPathComponent()  // iOS
        .appendingPathComponent("protocol/fixtures/stash/vectors.json")
}

private func loadStashVectors() throws -> StashVectors {
    let data = try Data(contentsOf: stashVectorsURL)
    return try JSONDecoder().decode(StashVectors.self, from: data)
}

/// Hex to bytes.
private func bytes(hex: String) -> Data {
    var out = Data()
    var index = hex.startIndex
    while index < hex.endIndex {
        let next = hex.index(index, offsetBy: 2)
        out.append(UInt8(hex[index..<next], radix: 16) ?? 0)
        index = next
    }
    return out
}

/// Base64 to bytes.
private func base64(_ text: String) -> Data {
    Data(base64Encoded: text) ?? Data()
}

/// Bytes to lowercase hex.
private func hex(_ data: Data) -> String {
    data.map { String(format: "%02x", $0) }.joined()
}

/// What the transport saw, without mutating a captured variable from a
/// concurrently-executing closure.
private actor RequestRecorder {
    private(set) var request: URLRequest?
    private(set) var credential: String?

    func record(_ request: URLRequest) {
        self.request = request
        credential = request.value(forHTTPHeaderField: "x-stash-cred")
    }
}

/// A transport that answers from a closure, so no test opens a socket.
private struct StashStubTransport: HTTPTransport {
    let answer: @Sendable (URLRequest) async throws -> (Data, HTTPURLResponse)

    func data(for request: URLRequest) async throws -> (Data, HTTPURLResponse) {
        try await answer(request)
    }
}

private func httpResponse(_ request: URLRequest, status: Int) -> HTTPURLResponse {
    HTTPURLResponse(
        url: request.url ?? URL(string: "https://relay.example.com/r/ROOM")!,
        statusCode: status,
        httpVersion: "HTTP/1.1",
        headerFields: nil,
    )!
}

/// The one fixture envelope, as the relay would hand it over.
private func pulled(_ envelope: StashVectors.Envelope) -> StashPulledEnvelope {
    StashPulledEnvelope(
        bundleId: envelope.bundleId,
        sessionId: "dsh:session-76fadc3d-4383-4ede-8bbf-39b0fcdea9fd",
        createdAt: envelope.createdAt,
        bytes: base64(envelope.envelope).count,
        envelope: base64(envelope.envelope),
    )
}

/// A client for the fixture's pairing.
private func fixtureClient(transport: (any HTTPTransport)? = nil) throws -> StashClient {
    let vectors = try loadStashVectors()
    let client = StashClient(
        relayBaseURL: "https://relay.example.com/r/\(vectors.derivation.room)",
        hostId: "host-fixture-0001",
        deviceId: "dev-fixture-0001",
        deviceToken: vectors.derivation.token,
        transport: transport ?? StashStubTransport { request in
            (Data(), httpResponse(request, status: 404))
        },
    )
    return try #require(client)
}

/// A decrypted bundle from the `one-turn` vector.
private func oneTurnBundle() throws -> StashBundle {
    let vectors = try loadStashVectors()
    let envelope = try #require(vectors.envelopes.first { $0.name == "one-turn" })
    return try #require(fixtureClient().open(pulled(envelope)))
}

// MARK: - Derivation and framing

@Suite("Offline stash wire contract")
struct StashWireTests {
    @Test("the derivation matches the cross-language vector")
    func derivation() throws {
        let vectors = try loadStashVectors()
        let credentials = try #require(
            StashCredentials(deviceToken: vectors.derivation.token, room: vectors.derivation.room),
        )
        #expect(credentials.tokenHash == vectors.derivation.tokenHash)
        #expect(hex(credentials.keyBytes) == vectors.derivation.key)
        #expect(credentials.cred == vectors.derivation.cred)
    }

    @Test("the room is the last path component of the relay base")
    func roomFromBaseURL() {
        #expect(
            StashCredentials.room(inRelayBaseURL: "https://relay.example.com/r/X43A3N64Q9FE")
                == "X43A3N64Q9FE",
        )
        #expect(
            StashCredentials.room(inRelayBaseURL: "https://relay.example.com/r/X43A3N64Q9FE/")
                == "X43A3N64Q9FE",
        )
        #expect(StashCredentials.room(inRelayBaseURL: "https://relay.example.com") == nil)
    }

    @Test("sealing the fixture plaintext reproduces the fixture envelope byte for byte")
    func envelopeBytes() throws {
        let vectors = try loadStashVectors()
        let credentials = try #require(
            StashCredentials(deviceToken: vectors.derivation.token, room: vectors.derivation.room),
        )
        for vector in vectors.envelopes {
            let sealed = try StashEnvelope.seal(
                plaintext: Data(vector.plaintext.utf8),
                key: credentials.key,
                nonce: bytes(hex: vector.nonce),
                aad: vector.aad,
            )
            #expect(sealed.base64EncodedString() == vector.envelope, "\(vector.name) does not match the fixture")
        }
    }

    @Test("opening the fixture envelope returns the fixture plaintext")
    func envelopeRoundTrip() throws {
        let vectors = try loadStashVectors()
        let credentials = try #require(
            StashCredentials(deviceToken: vectors.derivation.token, room: vectors.derivation.room),
        )
        for vector in vectors.envelopes {
            let opened = try StashEnvelope.open(
                base64(vector.envelope),
                key: credentials.key,
                aad: vector.aad,
            )
            #expect(String(decoding: opened, as: UTF8.self) == vector.plaintext)
        }
    }

    @Test("a wrong AAD or a wrong key is a rejection, not plaintext")
    func envelopeRejectsWrongContext() throws {
        let vectors = try loadStashVectors()
        let credentials = try #require(
            StashCredentials(deviceToken: vectors.derivation.token, room: vectors.derivation.room),
        )
        let vector = try #require(vectors.envelopes.first)
        #expect(throws: StashError.authenticationFailed) {
            try StashEnvelope.open(
                base64(vector.envelope),
                key: credentials.key,
                aad: vector.aad + "|x",
            )
        }
        let otherKey = SymmetricKey(size: .bits256)
        #expect(throws: StashError.authenticationFailed) {
            try StashEnvelope.open(base64(vector.envelope), key: otherKey, aad: vector.aad)
        }
    }

    @Test("an unknown version byte is skipped without a key")
    func envelopeVersion() throws {
        let vectors = try loadStashVectors()
        var raw = base64(try #require(vectors.envelopes.first).envelope)
        raw[0] = 2
        #expect(throws: StashError.unsupportedVersion) {
            try StashEnvelope.open(raw, key: SymmetricKey(size: .bits256), aad: "irrelevant")
        }
    }
}

// MARK: - Bundle decoding

@Suite("Offline stash bundle")
struct StashBundleTests {
    @Test("the one-turn vector decodes into the turn the wire spec describes")
    func bundleFields() throws {
        let bundle = try oneTurnBundle()
        #expect(bundle.v == 1)
        #expect(bundle.room == "X43A3N64Q9FE")
        #expect(bundle.hostId == "host-fixture-0001")
        #expect(bundle.deviceId == "dev-fixture-0001")
        #expect(bundle.epoch == 7)
        #expect(bundle.turns.count == 1)

        let turn = try #require(bundle.turns.first)
        #expect(turn.sessionId == "dsh:session-76fadc3d-4383-4ede-8bbf-39b0fcdea9fd")
        #expect(turn.turn == 12)
        #expect(turn.state == 11)
        #expect(turn.interval == 58)
        #expect(turn.textSeq == 2710)
        #expect(turn.truncated == false)
        #expect(turn.entries.count == 3)
        #expect(turn.bodyText == "改好了。")
    }

    @Test("the turn is a StreamReplay the rest of the app can read")
    func bundleReplay() throws {
        let bundle = try oneTurnBundle()
        let replay = try #require(bundle.turns.first).replay
        #expect(replay.sessionId == "dsh:session-76fadc3d-4383-4ede-8bbf-39b0fcdea9fd")
        #expect(replay.turn == 12)
        #expect(replay.state == 11)
        #expect(replay.interval == 58)
        #expect(replay.textSeq == 2710)
        #expect(replay.truncated == false)
        #expect(replay.entries.map(\.interval) == [55, 56, 58])
        #expect(replay.entries.map(\.final) == [false, false, true])
        #expect(replay.entries.last?.text == "改好了。")
    }

    @Test("only the narration becomes the process text, never the answer")
    func processBlocks() throws {
        let bundle = try oneTurnBundle()
        let turn = try #require(bundle.turns.first)
        let record = StashedReplay(
            hostId: bundle.hostId,
            sessionId: turn.sessionId,
            turn: turn.turn,
            epoch: bundle.epoch,
            replay: turn.replay,
            endedAt: turn.endedDate,
            bundleId: bundle.bundleId,
            createdAt: bundle.createdAt,
        )
        // The final body is the turn's answer and is drawn by the turn itself;
        // the narration before it is what only the letter has.
        #expect(record.processBlocks.map(\.text) == ["我先看一下…"])
    }
}

// MARK: - Merging into the phone's history

@Suite("Offline stash merge")
struct StashIngestTests {
    /// A store in a fresh temporary directory.
    private func makeStore() -> StashReplayStore {
        let directory = FileManager.default.temporaryDirectory
            .appendingPathComponent("stash-tests-\(UUID().uuidString)", isDirectory: true)
        return StashReplayStore(directory: directory)
    }

    @Test("a turn history does not have is synthesized as an ended turn")
    func synthesizesMissingTurn() async throws {
        let bundle = try oneTurnBundle()
        let cache = InMemoryConversationCache()
        let store = makeStore()

        let result = await StashIngest.apply(
            bundle: bundle,
            hostId: "host-fixture-0001",
            conversations: cache,
            process: store,
        )

        #expect(result.sessions == ["dsh:session-76fadc3d-4383-4ede-8bbf-39b0fcdea9fd"])
        let stored = try #require(await cache.load(sessionId: "dsh:session-76fadc3d-4383-4ede-8bbf-39b0fcdea9fd"))
        let turns = try #require(stored.turns)
        let turn = try #require(turns.first)
        #expect(turn.turn == 12)
        #expect(turn.prompts.isEmpty)
        #expect(turn.stepCount == 3)
        #expect(turn.endedReason == "completed")
        #expect(turn.failed == false)
        #expect(turn.endedAt == Date(timeIntervalSince1970: 1_795_088_000))
        #expect(turn.startedAt == Date(timeIntervalSince1970: 1_795_087_000))
        let answer = try #require(turn.steps.first)
        guard case .message(let id, .assistant, let text, _) = answer else {
            Issue.record("the synthesized step is not an assistant message")
            return
        }
        #expect(id == "stash-turn-12")
        #expect(text == "改好了。")
        // The item list is what the page notices as non-empty before it draws
        // turns at all.
        #expect(stored.items.count == 1)

        let records = await store.load(
            hostId: "host-fixture-0001",
            sessionId: "dsh:session-76fadc3d-4383-4ede-8bbf-39b0fcdea9fd",
        )
        #expect(records.map(\.turn) == [12])
        #expect(records.first?.bundleId == bundle.bundleId)
    }

    @Test("a turn history already has keeps its answer and only gains process text")
    func keepsExistingTurn() async throws {
        let bundle = try oneTurnBundle()
        let cache = InMemoryConversationCache()
        let store = makeStore()
        let existing = ConversationTurn(
            turn: 12,
            prompts: [],
            steps: [
                .message(
                    id: "seq-900",
                    role: .assistant,
                    text: "历史里的答案",
                    at: Date(timeIntervalSince1970: 1_795_088_000),
                ),
            ],
            stepCount: 1,
            startedAt: Date(timeIntervalSince1970: 1_795_087_000),
            endedAt: Date(timeIntervalSince1970: 1_795_088_000),
            endedReason: "completed",
        )
        await cache.save(
            CachedConversation(
                sessionId: "dsh:session-76fadc3d-4383-4ede-8bbf-39b0fcdea9fd",
                items: existing.items,
                throughSeq: nil,
                turns: [existing],
            ),
        )

        let result = await StashIngest.apply(
            bundle: bundle,
            hostId: "host-fixture-0001",
            conversations: cache,
            process: store,
        )

        #expect(result.synthesized.isEmpty)
        let stored = try #require(await cache.load(sessionId: "dsh:session-76fadc3d-4383-4ede-8bbf-39b0fcdea9fd"))
        #expect(stored.turns == [existing])
        // The process text is stored even though the turn was not synthesized:
        // that is the part the history never had.
        let records = await store.load(
            hostId: "host-fixture-0001",
            sessionId: "dsh:session-76fadc3d-4383-4ede-8bbf-39b0fcdea9fd",
        )
        #expect(records.count == 1)
        #expect(records.first?.processBlocks.map(\.text) == ["我先看一下…"])
    }

    @Test("the same turn keeps only its newest record")
    func latestRecordWins() async throws {
        let bundle = try oneTurnBundle()
        let turn = try #require(bundle.turns.first)
        let store = makeStore()
        let first = StashedReplay(
            hostId: "h",
            sessionId: "s",
            turn: 3,
            epoch: 1,
            replay: turn.replay,
            endedAt: nil,
            bundleId: "first",
            createdAt: 1,
            storedAt: Date(timeIntervalSinceNow: -100),
        )
        let second = StashedReplay(
            hostId: "h",
            sessionId: "s",
            turn: 3,
            epoch: 2,
            replay: turn.replay,
            endedAt: nil,
            bundleId: "second",
            createdAt: 2,
            storedAt: Date(timeIntervalSinceNow: -50),
        )
        await store.save(first)
        await store.save(second)
        let loaded = await store.load(hostId: "h", sessionId: "s")
        #expect(loaded.map(\.bundleId) == ["second"])
    }
}

// MARK: - Pulling

@Suite("Offline stash pull")
struct StashPullTests {
    @Test("a 404 is 'no stash', not an error")
    func notAvailable() async throws {
        let client = try fixtureClient(
            transport: StashStubTransport { request in
                (Data(), httpResponse(request, status: 404))
            },
        )
        #expect(try await client.pull() == .notAvailable)
    }

    @Test("a pull decodes its envelopes and sends the credential")
    func decodesPull() async throws {
        let vectors = try loadStashVectors()
        let vector = try #require(vectors.envelopes.first)
        let body = try JSONSerialization.data(withJSONObject: [
            "bundles": [
                [
                    "bundleId": vector.bundleId,
                    "sessionId": "dsh:session-76fadc3d-4383-4ede-8bbf-39b0fcdea9fd",
                    "createdAt": vector.createdAt,
                    "bytes": base64(vector.envelope).count,
                    "envelope": vector.envelope,
                ],
            ],
        ])
        let recorder = RequestRecorder()
        let client = try fixtureClient(
            transport: StashStubTransport { request in
                await recorder.record(request)
                return (body, httpResponse(request, status: 200))
            },
        )
        let result = try await client.pull()
        let seen = await recorder.request
        let credential = await recorder.credential
        guard case .bundles(let pulled) = result else {
            Issue.record("expected bundles, got \(result)")
            return
        }
        #expect(pulled.count == 1)
        #expect(pulled.first?.bundleId == vector.bundleId)
        #expect(credential == vectors.derivation.cred)
        #expect(seen?.url?.path == "/r/\(vectors.derivation.room)/stash/v1/pull")
        #expect(seen?.url?.query == "max=32")
        // The envelope the pull carried still opens with the AAD the client
        // rebuilds from the pairing, not from anything the relay sent.
        #expect(client.open(try #require(pulled.first)) != nil)
    }

    @Test("an unreadable envelope is skipped rather than thrown")
    func badEnvelopeIsSkipped() throws {
        let vectors = try loadStashVectors()
        let vector = try #require(vectors.envelopes.first)
        let client = try fixtureClient()
        // Version 2: a newer desktop's framing, which this build must ignore.
        var newer = base64(vector.envelope)
        newer[0] = 2
        let versioned = StashPulledEnvelope(
            bundleId: vector.bundleId,
            sessionId: "s",
            createdAt: vector.createdAt,
            envelope: newer,
        )
        #expect(client.open(versioned) == nil)
        // Garbage at a version this build knows.
        let broken = StashPulledEnvelope(
            bundleId: vector.bundleId,
            sessionId: "s",
            createdAt: vector.createdAt,
            envelope: Data([1, 0] + Array(repeating: 0, count: 40)),
        )
        #expect(client.open(broken) == nil)
    }

    @Test("a non-404 failure is an error the caller may swallow")
    func serverError() async throws {
        let client = try fixtureClient(
            transport: StashStubTransport { request in
                (Data(), httpResponse(request, status: 500))
            },
        )
        await #expect(throws: StashError.httpStatus(500)) {
            try await client.pull()
        }
    }
}

// MARK: - The hello capability

@Suite("Offline stash capability")
struct StashCapabilityTests {
    private func members(_ frame: ClientFrame) throws -> [String: JSONValue] {
        let data = try JSONEncoder().encode(frame)
        return try #require(try JSONDecoder().decode(JSONValue.self, from: data).objectValue)
    }

    @Test("hello advertises the capability at the top level")
    func helloAdvertises() throws {
        let frame = ClientFrame.hello(
            id: nil,
            token: "mz_x",
            appVersion: nil,
            deviceModel: nil,
            capabilities: ["stash.v1"],
        )
        let members = try members(frame)
        #expect(members["v"]?.intValue == mizarProtocolVersion)
        #expect(members["protocolVersion"]?.intValue == mizarProtocolVersion)
        #expect(members["capabilities"]?.arrayValue?.compactMap(\.stringValue) == ["stash.v1"])
    }

    @Test("a hello without capabilities sends no key at all")
    func helloWithoutCapabilities() throws {
        let members = try members(
            ClientFrame.hello(id: nil, token: "mz_x", appVersion: nil, deviceModel: nil),
        )
        #expect(members["capabilities"] == nil)
    }
}
